params.bodyScript:
// Groups catalog
// Each: {name, els:[names], op:(i,j)->k, subgroups:[{name, indices}]}
function mkZn(n){
  return {
    name:`ℤ/${n}ℤ`,
    els: Array.from({length:n},(_,i)=>String(i)),
    op:(i,j)=>mod(i+j,n),
    identity:0,
    abelian:true,
    subgroups: (()=>{
      const subs=[{name:'{e}',idx:[0]}];
      for(let d=2;d<=n;d++){
        if(n%d===0){
          const idx=[];
          for(let i=0;i<d;i++) idx.push((n/d)*i);
          subs.push({name:`⟨${n/d}⟩ order ${d}`,idx});
        }
      }
      return subs;
    })(),
  };
}
// V4 = Z2 x Z2: elements e=(0,0), a=(1,0), b=(0,1), ab=(1,1)
const V4 = (()=>{
  const els = ['e','a','b','ab'];
  const tbl = [[0,1,2,3],[1,0,3,2],[2,3,0,1],[3,2,1,0]];
  return {name:'V₄',els,op:(i,j)=>tbl[i][j],identity:0,abelian:true,
    subgroups:[
      {name:'{e}',idx:[0]},
      {name:'⟨a⟩',idx:[0,1]},
      {name:'⟨b⟩',idx:[0,2]},
      {name:'⟨ab⟩',idx:[0,3]},
      {name:'V₄ (whole)',idx:[0,1,2,3]},
    ],
  };
})();
// S3 via permutations
const S3 = (()=>{
  const perms = [[0,1,2],[1,0,2],[2,1,0],[0,2,1],[1,2,0],[2,0,1]];
  const names = ['e','(12)','(13)','(23)','(123)','(132)'];
  function apply(p,q){ return q.map(k=>p[k]); } // (p∘q)(k) = p(q(k))
  const op=(i,j)=>{
    const r = apply(perms[i],perms[j]);
    return perms.findIndex(p=>p.every((v,k)=>v===r[k]));
  };
  return {name:'S₃',els:names,op,identity:0,abelian:false,
    subgroups:[
      {name:'{e}',idx:[0]},
      {name:'⟨(12)⟩',idx:[0,1]},
      {name:'⟨(13)⟩',idx:[0,2]},
      {name:'⟨(23)⟩',idx:[0,3]},
      {name:'A₃ = ⟨(123)⟩',idx:[0,4,5]},
      {name:'S₃ (whole)',idx:[0,1,2,3,4,5]},
    ],
  };
})();
// D4: 1, r, r^2, r^3, s, sr, sr^2, sr^3; relations r^4=1, s^2=1, srs=r^-1
const D4 = (()=>{
  // represent as (i, f) where i ∈ {0,1,2,3} rotation, f∈{0,1} flip
  // product: (i1,f1)*(i2,f2) : r^i1 s^f1 r^i2 s^f2.  s r = r^-1 s, so s^f1 r^i2 = r^{(-1)^f1 i2} s^f1
  // => = r^{i1 + (-1)^f1 i2} s^{f1+f2}
  const names = ['1','r','r²','r³','s','sr','sr²','sr³'];
  const idx=(i,f)=>f*4+i;
  const decode = k=>({i:k%4,f:Math.floor(k/4)});
  const op=(a,b)=>{
    const A=decode(a),B=decode(b);
    const i = mod(A.i + (A.f?-1:1)*B.i, 4);
    const f = (A.f+B.f)%2;
    return idx(i,f);
  };
  return {name:'D₄',els:names,op,identity:0,abelian:false,
    subgroups:[
      {name:'{e}',idx:[0]},
      {name:'⟨r²⟩',idx:[0,2]},
      {name:'⟨s⟩',idx:[0,4]},
      {name:'⟨sr⟩',idx:[0,5]},
      {name:'⟨sr²⟩',idx:[0,6]},
      {name:'⟨sr³⟩',idx:[0,7]},
      {name:'⟨r⟩ order 4',idx:[0,1,2,3]},
      {name:'⟨s,r²⟩ ≅ V₄',idx:[0,2,4,6]},
      {name:'⟨sr,r²⟩ ≅ V₄',idx:[0,2,5,7]},
      {name:'D₄ (whole)',idx:[0,1,2,3,4,5,6,7]},
    ],
  };
})();
// Q8: {1,-1, i,-i, j,-j, k,-k} with i^2=j^2=k^2=ijk=-1
const Q8 = (()=>{
  const names=['1','−1','i','−i','j','−j','k','−k'];
  // represent as signed basis: 0:1 1:-1 2:i 3:-i 4:j 5:-j 6:k 7:-k
  const b = n=>({s:(n%2)?-1:1, e:Math.floor(n/2)}); // e ∈ 0..3 means 1,i,j,k
  const enc=(s,e)=>e*2+(s<0?1:0);
  // basis multiplication table (rows/cols are 1,i,j,k)
  // relations: i²=j²=k²=-1, ij=k, jk=i, ki=j, ji=-k, kj=-i, ik=-j
  const Q = [
    [{s:+1,e:0},{s:+1,e:1},{s:+1,e:2},{s:+1,e:3}],
    [{s:+1,e:1},{s:-1,e:0},{s:+1,e:3},{s:-1,e:2}],
    [{s:+1,e:2},{s:-1,e:3},{s:-1,e:0},{s:+1,e:1}],
    [{s:+1,e:3},{s:+1,e:2},{s:-1,e:1},{s:-1,e:0}],
  ];
  const op=(a,bi)=>{
    const A=b(a), B=b(bi);
    const r = Q[A.e][B.e];
    const s = A.s*B.s*r.s;
    return enc(s, r.e);
  };
  return {name:'Q₈',els:names,op,identity:0,abelian:false,
    subgroups:[
      {name:'{e}',idx:[0]},
      {name:'{±1}',idx:[0,1]},
      {name:'⟨i⟩ ≅ ℤ/4',idx:[0,1,2,3]},
      {name:'⟨j⟩ ≅ ℤ/4',idx:[0,1,4,5]},
      {name:'⟨k⟩ ≅ ℤ/4',idx:[0,1,6,7]},
      {name:'Q₈ (whole)',idx:[0,1,2,3,4,5,6,7]},
    ],
  };
})();
// A4: even permutations of {1,2,3,4} — 12 elements
const A4 = (()=>{
  // generate all permutations of [0,1,2,3] and filter even
  function permutations(arr){
    if(arr.length<=1) return [arr];
    const out=[];
    for(let i=0;i<arr.length;i++){
      const rest = arr.slice(0,i).concat(arr.slice(i+1));
      for(const p of permutations(rest)) out.push([arr[i],...p]);
    }
    return out;
  }
  function sign(p){
    let s=1;
    for(let i=0;i<p.length;i++) for(let j=i+1;j<p.length;j++) if(p[i]>p[j]) s=-s;
    return s;
  }
  function toCycleName(p){
    const n=p.length;
    const seen=new Array(n).fill(false);
    const cycles=[];
    for(let i=0;i<n;i++){
      if(seen[i]||p[i]===i){seen[i]=true;continue}
      const cyc=[i];
      seen[i]=true;
      let j=p[i];
      while(j!==i){cyc.push(j);seen[j]=true;j=p[j]}
      cycles.push(cyc);
    }
    if(!cycles.length) return 'e';
    return cycles.map(c=>'('+c.map(x=>x+1).join('')+')').join('');
  }
  const all = permutations([0,1,2,3]).filter(p=>sign(p)===1);
  // sort: put e first, then 3-cycles, then 2,2-cycles (V4 inside A4)
  all.sort((a,b)=>{
    const sa = a.every((v,i)=>v===i)?0:1;
    const sb = b.every((v,i)=>v===i)?0:1;
    return sa-sb;
  });
  const names = all.map(toCycleName);
  const op=(i,j)=>{
    const r = all[j].map(k=>all[i][k]); // (a∘b)(k)=a(b(k))
    return all.findIndex(p=>p.every((v,k)=>v===r[k]));
  };
  // V4 inside A4: e, (12)(34), (13)(24), (14)(23) — the elements of order ≤ 2
  const V4idx = [];
  for(let i=0;i<all.length;i++){
    const p = all[i];
    const p2 = p.map(k=>p[k]);
    if(p2.every((v,k)=>v===k)) V4idx.push(i);
  }
  return {name:'A₄',els:names,op,identity:0,abelian:false,
    subgroups:[
      {name:'{e}',idx:[0]},
      {name:'V₄ (normal)',idx:V4idx},
      {name:'A₄ (whole)',idx:names.map((_,i)=>i)},
    ]
  };
})();

const GROUPS = {'V4':V4,'S3':S3,'D4':D4,'Q8':Q8,'A4':A4};
const gSel = $('#ca-group'), sSel = $('#ca-sub'), out = $('#ca-out'), ro = $('#ca-readout'), props = $('#ca-props');

function getGroup(){
  const v = gSel.value;
  if(v.startsWith('Zn:')) return mkZn(parseInt(v.split(':')[1]));
  return GROUPS[v];
}

function renderSubs(G){
  sSel.innerHTML='';
  for(const s of G.subgroups){
    const o = document.createElement('option'); o.value=G.subgroups.indexOf(s); o.textContent=s.name; sSel.appendChild(o);
  }
  sSel.value = 0;
}

function isNormal(G,H){
  const n=G.els.length;
  const inH = new Set(H.idx);
  for(let g=0; g<n; g++){
    for(const h of H.idx){
      // check g h g^{-1} ∈ H
      // find g^-1
      let ginv=-1;
      for(let k=0;k<n;k++) if(G.op(g,k)===G.identity && G.op(k,g)===G.identity){ginv=k;break}
      const ghginv = G.op(G.op(g,h),ginv);
      if(!inH.has(ghginv)) return false;
    }
  }
  return true;
}

function cosetOf(G,H,g){
  // left coset g·H
  const cs = new Set();
  for(const h of H.idx) cs.add(G.op(g,h));
  return cs;
}

function draw(){
  const G = getGroup();
  const H = G.subgroups[+sSel.value || 0];
  // assign a color to each coset
  const n = G.els.length;
  const cosetOf_ = g=>cosetOf(G,H,g);
  const seen = new Array(n).fill(-1);
  const cosets = [];
  for(let g=0; g<n; g++){
    if(seen[g]>=0) continue;
    const c = [...cosetOf_(g)];
    const id = cosets.length;
    for(const x of c) seen[x]=id;
    cosets.push(c);
  }
  // palette
  const palette = ['rgba(255,216,102,0.18)','rgba(88,196,221,0.18)','rgba(131,193,103,0.18)','rgba(224,122,95,0.18)',
    'rgba(179,157,219,0.18)','rgba(125,224,214,0.18)','rgba(247,143,179,0.18)','rgba(240,201,135,0.18)',
    'rgba(100,148,237,0.18)','rgba(189,216,107,0.18)','rgba(200,130,170,0.18)','rgba(160,160,255,0.18)'];
  const normal = isNormal(G,H);
  const order = G.els.length, subOrder = H.idx.length;
  const numCosets = order/subOrder;
  props.innerHTML = `|G|=${order} · |H|=${subOrder} · [G:H]=${numCosets} · ${G.abelian?'abelian':'non-abelian'} · subgroup ${normal?'<span style="color:var(--green)">normal</span>':'<span style="color:var(--pink)">NOT normal</span>'}`;

  // build table
  let html = '<div style="overflow:auto"><table class="cayley"><tr><td class="hdr">·</td>';
  for(let j=0;j<n;j++) html += `<td class="hdr">${G.els[j]}</td>`;
  html += '</tr>';
  for(let i=0;i<n;i++){
    html += `<tr><td class="hdr">${G.els[i]}</td>`;
    for(let j=0;j<n;j++){
      const v = G.op(i,j);
      const ri = seen[i], rj = seen[j]; // coset of i, coset of j
      // color by coset of the result
      const cc = seen[v];
      // if the row's g is in H, highlight more strongly (subgroup block)
      const gInH = H.idx.includes(i);
      const hInH = H.idx.includes(j);
      let bg = palette[cc % palette.length];
      let extra = '';
      if(gInH && hInH){ extra = ';outline:1.5px solid rgba(255,216,102,0.45);outline-offset:-1px;'; }
      html += `<td style="background:${bg}${extra}" title="${G.els[i]}·${G.els[j]}=${G.els[v]}">${G.els[v]}</td>`;
    }
    html += '</tr>';
  }
  html += '</table></div>';
  out.innerHTML = html;
  // readout
  ro.innerHTML = `Subgroup H = {${H.idx.map(k=>G.els[k]).join(', ')}}. ` +
    `Cosets partition G into ${numCosets} blocks of size ${subOrder}. ` +
    (normal
      ? `<span style="color:var(--green)">H is normal</span>, so G/H is a group of order ${numCosets}.`
      : `<span style="color:var(--pink)">H is not normal</span> (there exists g with gH ≠ Hg). No quotient.`);
}

gSel.addEventListener('change',()=>{renderSubs(getGroup());draw();});
sSel.addEventListener('change',draw);
renderSubs(getGroup()); draw();

params.scriptBodyLiteral:
/* =============================== SECTION 3: Dihedral =============================== */
(function(){
  const svg = $('#dih-svg');
  const W=820,H=340;
  const nSlider = $('#dih-n'), nLabel = $('#dih-nval');
  const ro = $('#dih-readout');
  const btnR = $('#dih-r'), btnS = $('#dih-s'), btnReset = $('#dih-reset');

  let n = 5;
  let a = 0, b = 0;       // current element r^a s^b
  let word = '';          // displayed word (right-to-left application history)
  // animation state: current drawn angles per vertex
  let drawnAngles = null;
  let targetAngles = null;
  let rafId = null;
  const cx = W/2, cy = H/2 + 10, rad = 115;

  function targetAngleOf(j){
    // angle = 2π·(a + (-1)^b · j)/n
    return 2*Math.PI*(a + (b?-1:1)*j)/n;
  }
  function recomputeTargets(){
    targetAngles = [];
    for(let j=0;j<n;j++) targetAngles.push(targetAngleOf(j));
  }
  function initDrawn(){
    drawnAngles = [];
    for(let j=0;j<n;j++) drawnAngles.push(targetAngleOf(j));
  }

  function animateTo(newA,newB){
    a = newA; b = newB;
    recomputeTargets();
    // normalize drawn angles to nearest target (rotate by multiples of 2π so transition is short)
    for(let j=0;j<n;j++){
      while(targetAngles[j] - drawnAngles[j] > Math.PI) drawnAngles[j] += 2*Math.PI;
      while(targetAngles[j] - drawnAngles[j] < -Math.PI) drawnAngles[j] -= 2*Math.PI;
    }
    if(rafId) cancelAnimationFrame(rafId);
    const t0 = performance.now();
    const dur = 400;
    const from = drawnAngles.slice();
    const to = targetAngles.slice();
    function step(t){
      const u = Math.min(1,(t-t0)/dur);
      const e = u<0.5? 2*u*u : -1 + (4-2*u)*u; // easeInOutQuad
      for(let j=0;j<n;j++) drawnAngles[j] = from[j] + (to[j]-from[j])*e;
      draw();
      if(u<1) rafId = requestAnimationFrame(step);
    }
    rafId = requestAnimationFrame(step);
  }

  function draw(){
    while(svg.firstChild) svg.removeChild(svg.firstChild);
    // axis of reflection (vertical line through center — s flips across the line through vertex 0)
    svg.appendChild(SVG('line',{x1:cx,y1:cy-rad-20,x2:cx,y2:cy+rad+20,stroke:'#3a4558','stroke-width':1,'stroke-dasharray':'4 6'}));
    // center dot
    svg.appendChild(SVG('circle',{cx,cy,r:2,fill:'#6c7787'}));
    // polygon edges
    let pts=[];
    for(let j=0;j<n;j++){
      const θ = drawnAngles[j];
      pts.push([cx + rad*Math.cos(θ), cy - rad*Math.sin(θ)]);
    }
    const poly = SVG('polygon',{points:pts.map(p=>p.join(',')).join(' '),
      fill:'rgba(88,196,221,0.08)',stroke:'#58c4dd','stroke-width':1.8});
    svg.appendChild(poly);
    // vertices
    for(let j=0;j<n;j++){
      const [x,y] = pts[j];
      const col = j===0?'#ffd866':(j===1?'var(--green)':'#58c4dd');
      svg.appendChild(SVG('circle',{cx:x,cy:y,r:7,fill:col,stroke:'#fff','stroke-width':1.5}));
      const t = SVG('text',{x,y:y+0.5,'font-size':12,'text-anchor':'middle','dominant-baseline':'central',fill:'#111','font-weight':700});
      t.textContent = j+1;
      svg.appendChild(t);
    }
    // word + element display
    const elTxt = b? (a===0?'s':`r${a===1?'':sup(a)}s`) : (a===0?'e':`r${a===1?'':sup(a)}`);
    const elLbl = SVG('text',{x:30,y:30,'font-size':15,fill:'#fff'});
    elLbl.textContent = `current element g = ${elTxt}`;
    svg.appendChild(elLbl);
    const wLbl = SVG('text',{x:30,y:55,'font-size':12,fill:'#9aa4b2'});
    wLbl.textContent = `word applied: ${word||'(identity)'}`;
    svg.appendChild(wLbl);
    // permutation
    const perm = [];
    for(let j=0;j<n;j++){
      // vertex labeled j is drawn at angle 2π(a + (-1)^b · j)/n
      // the position originally held vertex k where 2πk/n = same angle
      // so the vertex at original position k is now labeled j=? Actually we're showing: vertex j at position (a + (-1)^b j). So the permutation sending "original position p" to "new label at that position" is: at position p, the vertex with label j where (a + (-1)^b j) mod n = p → j = (-1)^b (p - a) mod n.
      perm.push(mod((b?-(j-a):(j-a)),n)+1); // label at original position j
    }
    // cycle decomposition for display
    function cycles(p){ // p is 1-indexed array where p[i] = label at position i+1
      const nn = p.length, seen = new Array(nn).fill(false), res=[];
      for(let i=0;i<nn;i++){
        if(seen[i]||p[i]===i+1){seen[i]=true;continue}
        const c=[i+1]; seen[i]=true;
        let j=p[i]-1;
        while(j!==i){c.push(j+1);seen[j]=true;j=p[j]-1}
        if(c.length>1) res.push(c);
      }
      return res.length?res.map(c=>'('+c.join('\u00a0')+')').join(''):'e';
    }
    ro.innerHTML = `element g = <b style="color:var(--yellow)">${elTxt}</b> · order |g| = ${orderOf(a,b,n)} · as permutation of vertices: <span style="color:var(--blue)">${cycles(perm)}</span> · ` +
      (b? `<span style="color:var(--pink)">reflection</span>`:`<span style="color:var(--green)">rotation</span>`);
  }
  function sup(x){ return ''+[...String(x)].map(d=>'⁰¹²³⁴⁵⁶⁷⁸⁹'[+d]).join(''); }
  function orderOf(a,b,n){
    if(b===0){ return n/gcd(a,n); }
    return 2; // any reflection has order 2
  }

  function applyR(){
    // new = r · current = r^(a+1) s^b
    const na = mod(a+1,n), nb=b;
    word = word + 'r';
    animateTo(na,nb);
  }
  function applyS(){
    // new = s · current = r^(-a) s^(b+1)
    const na = mod(-a,n), nb = (b+1)%2;
    word = word + 's';
    animateTo(na,nb);
  }
  function reset(){
    word=''; animateTo(0,0);
  }
  btnR.addEventListener('click',applyR);
  btnS.addEventListener('click',applyS);
  btnReset.addEventListener('click',reset);
  nSlider.addEventListener('input',()=>{
    n = parseInt(nSlider.value);
    nLabel.textContent = n;
    a = mod(a,n);
    word='';
    initDrawn();
    recomputeTargets();
    draw();
  });

  initDrawn();
  recomputeTargets();
  draw();
})();

