const svg = $('#clk-svg');
const W=820, H=360;
const nS=$('#clk-n'), aS=$('#clk-a'), bS=$('#clk-b');
const nV=$('#clk-nval'), aV=$('#clk-aval'), bV=$('#clk-bval');
const info = $('#clk-info'), ro = $('#clk-readout');

function draw(){
  const n = +nS.value; const a = mod(+aS.value, n); const b = mod(+bS.value, n);
  nV.textContent=n; aV.textContent=a; bV.textContent=b;
  aS.max = n-1; bS.max = n-1;
  aS.value = a; bS.value = b;

  const phi = euler(n);
  const prime = isPrime(n);
  info.innerHTML = `|ℤ/${n}ℤ| = ${n} · units |(ℤ/${n}ℤ)ˣ| = φ(${n}) = ${phi} · ${prime?`<span style="color:var(--green)">${n} is prime ⇒ field 𝔽<sub>${n}</sub></span>`:`<span style="color:var(--pink)">${n} composite ⇒ has zero divisors</span>`}`;

  while(svg.firstChild) svg.removeChild(svg.firstChild);
  const cx = 260, cy=H/2, rad=130;
  // clock face
  svg.appendChild(SVG('circle',{cx,cy,r:rad+22,fill:'none',stroke:'#2a3242'}));
  const dots = [];
  for(let k=0;k<n;k++){
    const θ = 2*Math.PI*k/n - Math.PI/2;
    const x = cx + rad*Math.cos(θ), y = cy + rad*Math.sin(θ);
    const g = gcd(k,n);
    const isUnit = (k!==0 && g===1);
    const isZD = (k!==0 && g!==1);
    const color = k===0? '#9aa4b2' : (isUnit? 'var(--green)' : '#e07a5f');
    const dot = SVG('circle',{cx:x,cy:y,r:10,fill:color,stroke:'#fff','stroke-width':1});
    svg.appendChild(dot);
    const t = SVG('text',{x,y:y+4,'font-size':12,'text-anchor':'middle',fill:'#111','font-weight':700});
    t.textContent = k; svg.appendChild(t);
    dots.push({x,y,k,color});
  }
  // arrows for a, a+b, a·b
  function arrow(from,to,color,label,offset=0){
    const ang = Math.atan2(to.y-from.y, to.x-from.x);
    const fx=from.x+12*Math.cos(ang), fy=from.y+12*Math.sin(ang);
    const tx=to.x-12*Math.cos(ang), ty=to.y-12*Math.sin(ang);
    svg.appendChild(SVG('line',{x1:fx,y1:fy,x2:tx,y2:ty,stroke:color,'stroke-width':2+offset,'stroke-opacity':0.85,'marker-end':'url(#arrow'+color.slice(1)+')'}));
  }
  // arrow markers (one per color)
  function addMarker(color,id){
    const d = document.createElementNS('http://www.w3.org/2000/svg','defs');
    d.innerHTML = `<marker id="${id}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="${color}"/></marker>`;
    svg.appendChild(d);
  }
  addMarker('#58c4dd','arrowA'); addMarker('var(--green)','arrowB'); addMarker('#ffd866','arrowSum'); addMarker('#e07a5f','arrowProd');

  // show chord from 0 to a (blue)
  function posOf(k){ const θ=2*Math.PI*k/n-Math.PI/2; return {x:cx+rad*Math.cos(θ),y:cy+rad*Math.sin(θ)}; }
  const P0 = posOf(0), Pa = posOf(a), Pb = posOf(b), Psum = posOf(mod(a+b,n)), Pprod = posOf(mod(a*b,n));
  function drawArrow(P1,P2,markerId,color){
    const ang = Math.atan2(P2.y-P1.y, P2.x-P1.x);
    const fx = P1.x+12*Math.cos(ang), fy = P1.y+12*Math.sin(ang);
    const tx = P2.x-12*Math.cos(ang), ty = P2.y-12*Math.sin(ang);
    svg.appendChild(SVG('line',{x1:fx,y1:fy,x2:tx,y2:ty,stroke:color,'stroke-width':2,'marker-end':`url(#${markerId})`,'stroke-opacity':0.9}));
  }
  drawArrow(P0,Pa,'arrowA','#58c4dd');
  drawArrow(Pa,Psum,'arrowSum','#ffd866');
  // right side: explanation / table
  const boxX = 470, boxY=40;
  const lh = 26;
  const pairs = [
    ['a', `${a}`, '#58c4dd'],
    ['b', `${b}`, 'var(--green)'],
    ['a + b mod n', `${mod(a+b,n)}`, '#ffd866'],
    ['a · b mod n', `${mod(a*b,n)}`, '#e07a5f'],
    ['gcd(a,n)', `${gcd(a,n)}  ⇒  a is ${a===0?'zero':gcd(a,n)===1?'a unit':'a zero divisor'}`, gcd(a,n)===1&&a!==0?'var(--green)':(a===0?'#9aa4b2':'#e07a5f')],
  ];
  let y = boxY;
  for(const [k,v,c] of pairs){
    const t1 = SVG('text',{x:boxX,y,'font-size':14,fill:'#9aa4b2'});
    t1.textContent = k;
    const t2 = SVG('text',{x:boxX+150,y,'font-size':15,fill:c,'font-weight':600});
    t2.textContent = v;
    svg.appendChild(t1); svg.appendChild(t2); y+=lh;
  }
  // inverse lookup for a
  if(a!==0 && gcd(a,n)===1){
    let inv=-1;
    for(let i=1;i<n;i++) if(mod(a*i,n)===1){inv=i;break}
    const t1 = SVG('text',{x:boxX,y,'font-size':14,fill:'#9aa4b2'}); t1.textContent='a⁻¹ mod n';
    const t2 = SVG('text',{x:boxX+150,y,'font-size':15,fill:'var(--green)','font-weight':600}); t2.textContent=inv;
    svg.appendChild(t1); svg.appendChild(t2); y+=lh;
  }
  if(a!==0 && gcd(a,n)>1){
    // find b' with a*b' ≡ 0
    let zd=-1;
    for(let i=1;i<n;i++) if(mod(a*i,n)===0){zd=i;break}
    const t1 = SVG('text',{x:boxX,y,'font-size':14,fill:'#9aa4b2'}); t1.textContent='a · ? ≡ 0';
    const t2 = SVG('text',{x:boxX+150,y,'font-size':15,fill:'#e07a5f','font-weight':600}); t2.textContent=`a · ${zd} = ${a*zd} ≡ 0`;
    svg.appendChild(t1); svg.appendChild(t2); y+=lh;
  }
  // multiplication order of a (if unit): smallest k with a^k ≡ 1
  if(a!==0 && gcd(a,n)===1){
    let ord=1, v=a;
    while(v!==1){v=mod(v*a,n);ord++;if(ord>n){ord=-1;break}}
    const t1 = SVG('text',{x:boxX,y,'font-size':14,'font-size':14,fill:'#9aa4b2'}); t1.textContent='ord(a) in (ℤ/nℤ)ˣ';
    const t2 = SVG('text',{x:boxX+150,y,'font-size':15,fill:'#ffd866','font-weight':600}); t2.textContent=`${ord} (divides ${euler(n)})`;
    svg.appendChild(t1); svg.appendChild(t2); y+=lh;
  }

  ro.innerHTML = prime?
    `ℤ/${n}ℤ = 𝔽<sub>${n}</sub>. Every nonzero element is invertible. The multiplicative group (𝔽<sub>${n}</sub>)ˣ is cyclic of order ${n-1}.`
    : `ℤ/${n}ℤ is a ring but not a field. Zero divisors are the nonzero ${
        Array.from({length:n},(_,k)=>k).filter(k=>k!==0 && gcd(k,n)>1).join(', ')
      }. Units are 1, ${
        Array.from({length:n},(_,k)=>k).filter(k=>k!==0 && gcd(k,n)===1 && k!==1).join(', ')
      }.`;
}
nS.addEventListener('input',draw);
aS.addEventListener('input',draw);
bS.addEventListener('input',draw);
draw();

// Rationals with BigInt
function bgcd(a,b){a=a<0n?-a:a;b=b<0n?-b:b;while(b){[a,b]=[b,a%b]}return a||1n}
function normQ(n,d){ if(d<0n){n=-n;d=-d;} const g=bgcd(n,d); return {n:n/g,d:d/g}; }
const Q = {
  zero:{n:0n,d:1n}, one:{n:1n,d:1n},
  from:k => normQ(BigInt(k),1n),
  add:(a,b)=>normQ(a.n*b.d + b.n*a.d, a.d*b.d),
  sub:(a,b)=>normQ(a.n*b.d - b.n*a.d, a.d*b.d),
  mul:(a,b)=>normQ(a.n*b.n, a.d*b.d),
  div:(a,b)=>normQ(a.n*b.d, a.d*b.n),
  isZero:a=>a.n===0n,
  eq:(a,b)=>a.n*b.d===b.n*a.d,
  toStr:a=>a.d===1n? a.n.toString() : `${a.n}/${a.d}`,
  isNeg:a=>(a.n<0n)!==(a.d<0n),
  neg:a=>({n:-a.n,d:a.d}),
};
function mkFp(p){
  const P = BigInt(p);
  function inv(a){
    let [r0,r1]=[P,a], [s0,s1]=[0n,1n];
    while(r1){const q=r0/r1;[r0,r1]=[r1,r0-q*r1];[s0,s1]=[s1,s0-q*s1]}
    return ((s0%P)+P)%P;
  }
  return {
    zero:0n, one:1n,
    from:k=>((BigInt(k)%P)+P)%P,
    add:(a,b)=>((a+b)%P+P)%P,
    sub:(a,b)=>((a-b)%P+P)%P,
    mul:(a,b)=>((a*b)%P+P)%P,
    div:(a,b)=>{if(b===0n) throw 'div0'; return (a*inv(b))%P;},
    isZero:a=>a===0n,
    eq:(a,b)=>a===b,
    toStr:a=>a.toString(),
    isNeg:a=>false, // Fp: no canonical negatives
    neg:a=>((P-a)%P),
  };
}

function parsePoly(F, s){
  s = s.replace(/\s+/g,'').replace(/−/g,'-').replace(/\*\*/g,'^');
  if(!s) return [];
  if(s[0]!=='+' && s[0]!=='-') s = '+'+s;
  const re = /([+-])(\d*(?:\/\d+)?)?(\*?)(x(\^(\d+))?)?/g;
  const coeffs = [];
  let m;
  while((m = re.exec(s))){
    if(!m[0]) continue;
    const sign = m[1]==='-'?-1:1;
    let cStr = m[2]||'';
    let c;
    if(cStr===''){ c = F.from(1); }
    else if(cStr.includes('/')){
      const [n,d]=cStr.split('/').map(BigInt);
      c = (F===Q)? normQ(n,d) : F.div(F.from(n),F.from(d));
    } else {
      c = F.from(BigInt(cStr));
    }
    if(sign<0) c = F.sub(F.zero, c);
    let deg = 0;
    if(m[4]){ deg = m[6]? parseInt(m[6]):1; }
    while(coeffs.length<=deg) coeffs.push(F.zero);
    coeffs[deg] = F.add(coeffs[deg], c);
  }
  while(coeffs.length && F.isZero(coeffs[coeffs.length-1])) coeffs.pop();
  return coeffs;
}

function polyStr(F, c){
  if(c.length===0) return '0';
  const terms=[];
  for(let i=c.length-1;i>=0;i--){
    if(F.isZero(c[i])) continue;
    let s = F.toStr(c[i]);
    let neg = s.startsWith('-');
    if(neg) s = s.slice(1);
    let out = s;
    if(i>0){
      if(s==='1') out = '';
      out += 'x' + (i>1?('^'+i):'');
    }
    if(!terms.length){
      terms.push(neg?'−'+out:out);
    } else {
      terms.push(neg? ' − '+out : ' + '+out);
    }
  }
  return terms.join('')||'0';
}

function polyDivMod(F, a, b){
  if(b.length===0) throw 'div by zero polynomial';
  a = a.slice();
  const degB = b.length-1;
  let q = [];
  while(a.length-1 >= degB && a.length > 0){
    const degA = a.length-1;
    const c = F.div(a[degA], b[degB]);
    const shift = degA - degB;
    while(q.length < shift+1) q.push(F.zero);
    q[shift] = F.add(q[shift], c);
    for(let i=0;i<b.length;i++){
      a[shift+i] = F.sub(a[shift+i], F.mul(c, b[i]));
    }
    while(a.length && F.isZero(a[a.length-1])) a.pop();
  }
  return {q, r:a};
}

function monicize(F, a){
  if(a.length===0) return a;
  const lead = a[a.length-1];
  if(F.eq(lead, F.one)) return a;
  return a.map(c=>F.div(c, lead));
}

function polyGCD(F, a, b, steps){
  while(b.length > 0){
    const {q, r} = polyDivMod(F, a, b);
    steps.push({a:a.slice(), b:b.slice(), q, r});
    a = b; b = r;
    if(steps.length>30) break;
  }
  return monicize(F, a);
}

const ro = $('#eu-readout');
$$('.eubtn').forEach(btn=>btn.addEventListener('click',()=>{
  $('#eu-f').value = btn.dataset.f; $('#eu-g').value = btn.dataset.g; run();
}));
$('#eu-k').addEventListener('change',run);
$('#eu-f').addEventListener('input',run);
$('#eu-g').addEventListener('input',run);

function run(){
  const kv = $('#eu-k').value;
  const F = kv==='Q'? Q : mkFp(parseInt(kv.slice(1)));
  let f,g;
  try{ f = parsePoly(F, $('#eu-f').value); g = parsePoly(F, $('#eu-g').value); }
  catch(e){ ro.innerHTML = `<span style="color:var(--pink)">parse error: ${e}</span>`; return; }
  if(f.length===0 || g.length===0){
    ro.innerHTML = `<span style="color:var(--pink)">please enter two nonzero polynomials</span>`;
    return;
  }
  // make sure deg f >= deg g for display (but algo works either way)
  if(f.length < g.length){ [f,g] = [g,f]; }
  const steps = [];
  try{
    const gcd = polyGCD(F, f, g, steps);
    let html = '';
    html += `<div>f(x) = <span style="color:var(--blue)">${polyStr(F,f)}</span></div>`;
    html += `<div>g(x) = <span style="color:var(--green)">${polyStr(F,g)}</span></div>`;
    html += `<div style="margin-top:.5rem;color:var(--mute)">Euclidean steps (f<sub>i</sub> = q<sub>i</sub>·f<sub>i+1</sub> + f<sub>i+2</sub>):</div>`;
    for(let i=0;i<steps.length;i++){
      const s = steps[i];
      html += `<div style="margin-top:.35rem">step ${i+1}: (${polyStr(F,s.a)}) = (${polyStr(F,s.q)})·(${polyStr(F,s.b)}) + <span style="color:var(--yellow)">${polyStr(F,s.r)||'0'}</span></div>`;
    }
    html += `<div style="margin-top:.6rem;font-size:1.05em"><b>gcd(f,g) = <span style="color:var(--yellow)">${polyStr(F,gcd)||'1'}</span></b> (in ${kv==='Q'?'ℚ[x]':`𝔽${kv.slice(1)}[x]`})</div>`;
    // interpretation
    if(gcd.length<=1){
      html += `<div class="small" style="color:var(--green)">gcd is a nonzero constant ⇒ f and g are coprime in this ring.</div>`;
    } else {
      html += `<div class="small" style="color:var(--blue)">common factor of degree ${gcd.length-1} detected — f and g share an irreducible divisor.</div>`;
    }
    ro.innerHTML = html;
  } catch(e){ ro.innerHTML = `<span style="color:var(--pink)">error: ${e}</span>`; }
}
run();

