/* =============================== SECTION 6: Finite fields =============================== */
(function(){
  // precomputed monic irreducible polynomials (constant first)
  const IRR = {
    '2,2':[1,1,1],        // x^2 + x + 1
    '2,3':[1,1,0,1],      // x^3 + x + 1
    '2,4':[1,1,0,0,1],    // x^4 + x + 1
    '3,2':[1,0,1],        // x^2 + 1  (irreducible since -1 is non-residue mod 3)
    '3,3':[1,2,0,1],      // x^3 + 2x + 1 (irreducible over F_3)
    '3,4':[2,1,0,0,1],    // x^4 + x + 2 (irreducible over F_3)
    '5,2':[2,0,1],        // x^2 + 2 (irreducible: 2 is non-residue mod 5)
    '5,3':[1,1,0,1],      // x^3 + x + 1 (irreducible mod 5)
    '5,4':[2,0,0,0,1],    // x^4 + 2 — actually need to verify
  };

  const ro = $('#ff-readout');
  const info = $('#ff-info');
  const pSel = $('#ff-p'), nSel = $('#ff-n');

  function modp(a,p){ a = ((a%p)+p)%p; return a; }
  function polyAdd(a,b,p){
    const len = Math.max(a.length,b.length);
    const r = [];
    for(let i=0;i<len;i++) r.push(modp((a[i]||0)+(b[i]||0),p));
    while(r.length && r[r.length-1]===0) r.pop();
    return r;
  }
  function polyMul(a,b,p){
    if(a.length===0 || b.length===0) return [];
    const r = new Array(a.length+b.length-1).fill(0);
    for(let i=0;i<a.length;i++) for(let j=0;j<b.length;j++){
      r[i+j] = modp(r[i+j] + a[i]*b[j], p);
    }
    while(r.length && r[r.length-1]===0) r.pop();
    return r;
  }
  function polyMod(a,m,p){
    a = a.slice();
    const degM = m.length-1;
    // modular inverse
    function inv(x){
      for(let i=1;i<p;i++) if((i*x)%p===1) return i;
      return 0;
    }
    const invLead = inv(m[degM]);
    while(a.length-1 >= degM){
      const deg = a.length-1;
      const c = modp(a[deg]*invLead, p);
      const shift = deg-degM;
      for(let i=0;i<m.length;i++){
        a[shift+i] = modp(a[shift+i] - c*m[i], p);
      }
      while(a.length && a[a.length-1]===0) a.pop();
    }
    return a;
  }

  function enumerate(p, n){
    // list all p^n elements as coefficient arrays of length n (padded with 0s)
    const out = [];
    const N = Math.pow(p,n);
    for(let k=0;k<N;k++){
      const c=[];
      let kk = k;
      for(let i=0;i<n;i++){c.push(kk%p); kk = Math.floor(kk/p);}
      // trim trailing zeros for canonical form
      let e = c.slice();
      while(e.length && e[e.length-1]===0) e.pop();
      out.push(e);
    }
    return out;
  }
  function encode(c,p,n){
    let k=0;
    for(let i=n-1;i>=0;i--) k = k*p + (c[i]||0);
    return k;
  }
  function polyStr(c){
    if(!c.length) return '0';
    const terms=[];
    for(let i=c.length-1;i>=0;i--){
      if(c[i]===0) continue;
      let s = c[i]===1 && i>0 ? '' : ''+c[i];
      const alpha = i===0?'':(i===1?'α':`α${sup(i)}`);
      if(terms.length) terms.push(' + '+s+alpha);
      else terms.push(s+alpha);
    }
    return terms.join('')||'0';
  }
  function sup(x){ return ''+[...String(x)].map(d=>'⁰¹²³⁴⁵⁶⁷⁸⁹'[+d]).join(''); }

  function draw(){
    const p = parseInt(pSel.value);
    const n = parseInt(nSel.value);
    const key = `${p},${n}`;
    const m = IRR[key];
    if(!m){
      info.innerHTML = `<span style="color:var(--pink)">no irreducible polynomial configured</span>`;
      return;
    }
    const q = Math.pow(p,n);
    const all = enumerate(p,n);
    // encode/decode consistent
    // find primitive element: smallest index g (skipping 0 and 1) with order q-1
    let gIdx = -1;
    function ord(e){
      if(encode(e,p,n)===0) return 0;
      let x = [1], k=0;
      for(let i=1;i<=q-1;i++){
        x = polyMod(polyMul(x,e,p),m,p);
        if(encode(x,p,n)===1) return i;
      }
      return -1;
    }
    for(let k=2;k<q;k++){
      const e = all[k];
      if(ord(e)===q-1){gIdx = k; break}
    }
    // build discrete log: dlog[index] = power i such that g^i = element
    const dlog = new Array(q).fill(-1);
    if(gIdx>=0){
      const g = all[gIdx];
      let cur = [1];
      for(let i=0;i<q-1;i++){
        dlog[encode(cur,p,n)] = i;
        cur = polyMod(polyMul(cur,g,p),m,p);
      }
    }
    // Frobenius map: x → x^p
    function frob(e){
      let x=[1];
      for(let i=0;i<p;i++) x = polyMod(polyMul(x,e,p),m,p);
      return x;
    }

    info.innerHTML = `|𝔽<sub>${q}</sub>| = ${q} · irreducible m(x) = <span style="color:var(--yellow)">${polyStrX(m)}</span> · primitive element g = <span style="color:var(--yellow)">${polyStr(all[gIdx]||[])}</span>`;

    const svg = $('#ff-svg'); while(svg.firstChild) svg.removeChild(svg.firstChild);
    const W=820,H=420;
    // Display: 0 at center, nonzero elements on a circle in order of their discrete log
    const cx = W/2, cy = H/2+10, rad = Math.min(160, 120 + (q<10?40:0));
    // zero
    const zDot = SVG('circle',{cx:100,cy:60,r:8,fill:'#6c7787',stroke:'#fff','stroke-width':1,style:'cursor:pointer','data-idx':0});
    svg.appendChild(zDot);
    const zLbl = SVG('text',{x:115,y:64,'font-size':13,fill:'#9aa4b2'}); zLbl.textContent='0'; svg.appendChild(zLbl);
    // labeled cycle
    const cycleLbl = SVG('text',{x:cx,y:30,'font-size':13,'text-anchor':'middle',fill:'#fff'});
    cycleLbl.textContent = `multiplicative group 𝔽×${sup(q)} ≅ ℤ/${q-1}ℤ`;
    svg.appendChild(cycleLbl);

    const dots = [];
    for(let i=0;i<q-1;i++){
      const θ = 2*Math.PI*i/(q-1) - Math.PI/2;
      const x = cx + rad*Math.cos(θ);
      const y = cy + rad*Math.sin(θ);
      // which element has dlog i?
      const idx = dlog.indexOf(i);
      dots.push({idx,x,y,i});
      const d = SVG('circle',{cx:x,cy:y,r:8,fill:'#58c4dd',stroke:'#fff','stroke-width':1,style:'cursor:pointer','data-idx':idx});
      svg.appendChild(d);
      const lab = SVG('text',{x:x+ (Math.cos(θ)*14), y:y+(Math.sin(θ)*14)+4, 'font-size':11,'text-anchor':Math.cos(θ)>0.1?'start':(Math.cos(θ)<-0.1?'end':'middle'), fill:'#cbd5e1'});
      lab.textContent = i===0? '1' : (i===1?'g':`g${sup(i)}`);
      svg.appendChild(lab);
    }

    // Frobenius orbit coloring
    const orbitColor = ['#ffd866','#e07a5f','#b39ddb','var(--green)','#7de0d6','#f78fb3','#6495ed'];
    const orbit = new Array(q).fill(-1);
    let oc = 0;
    for(let k=0;k<q;k++){
      if(orbit[k]>=0) continue;
      let cur = all[k];
      let id = k;
      const pts = [];
      while(orbit[id]<0){
        orbit[id]=oc;
        pts.push(id);
        cur = frob(cur);
        id = encode(cur,p,n);
      }
      // optionally draw arrows between consecutive points in the orbit (if more than 1)
      if(pts.length>1 && k!==0){
        for(let j=0;j<pts.length;j++){
          const from = pts[j], to = pts[(j+1)%pts.length];
          if(from===0 || to===0) continue;
          const fi = dlog[from], ti = dlog[to];
          const θf = 2*Math.PI*fi/(q-1)-Math.PI/2;
          const θt = 2*Math.PI*ti/(q-1)-Math.PI/2;
          const fx = cx+(rad-12)*Math.cos(θf), fy = cy+(rad-12)*Math.sin(θf);
          const tx = cx+(rad-12)*Math.cos(θt), ty = cy+(rad-12)*Math.sin(θt);
          svg.appendChild(SVG('line',{x1:fx,y1:fy,x2:tx,y2:ty,stroke:orbitColor[oc%orbitColor.length],'stroke-width':1,'stroke-opacity':0.3}));
        }
      }
      oc++;
    }

    // click handler
    function showInfo(idx){
      const e = all[idx];
      const isZero = (encode(e,p,n)===0);
      if(isZero){
        ro.innerHTML = `<b>0</b> — the additive identity. Not in 𝔽×${sup(q)}. Frobenius: 0 ↦ 0.`;
        return;
      }
      const powi = dlog[idx];
      const ordEl = (q-1)/gcd(powi, q-1);
      const frobEl = frob(e);
      // minimal polynomial: find smallest d | n s.t. the orbit of e under Frob has size d. That's exactly the degree of the min poly.
      let orbPts = [e];
      let cur = frob(e);
      while(encode(cur,p,n)!==encode(e,p,n)){ orbPts.push(cur); cur = frob(cur); }
      const minDeg = orbPts.length;
      // construct min poly = prod (x - r) over r in orbit (in F_p[x])
      // work in coefficients in F_p, but the result will have coefficients in F_p (orbit is Galois-stable)
      // we'll compute as polynomials over F_{p^n}[x] and read off coefficients; but since the result is in F_p, we can encode each coefficient as an element of F_{p^n} and verify it's degree 0.
      // simpler: multiply (x - r_i) step by step over F_{p^n}, keeping polynomial whose coeffs are elements of F_{p^n} (each an array of length up to n).
      let P = [[1]]; // polynomial 1 over F_{p^n}
      for(const r of orbPts){
        // multiply P by (x - r) in (F_{p^n})[x]
        const Q = new Array(P.length+1).fill(0).map(()=>[]);
        // x * P
        for(let i=0;i<P.length;i++) Q[i+1] = polyAdd(Q[i+1], P[i], p);
        // -r * P
        const nr = polyMod(polyMul([0],[0],p),m,p); // placeholder
        const negR = r.map(c=>modp(-c,p));
        for(let i=0;i<P.length;i++){
          const prod = polyMod(polyMul(P[i], negR, p),m,p);
          Q[i] = polyAdd(Q[i], prod, p);
        }
        P = Q;
      }
      // coefficients of P should be constant polynomials; extract integer constants
      const coeffsFp = P.map(c => c.length===0? 0 : c[0]);
      const minPolyStr = (()=>{
        const terms=[];
        for(let i=coeffsFp.length-1;i>=0;i--){
          const c = coeffsFp[i];
          if(c===0) continue;
          let s = c===1 && i>0 ? '' : ''+c;
          const xp = i===0?'':(i===1?'x':`x${sup(i)}`);
          if(terms.length) terms.push(' + '+s+xp);
          else terms.push(s+xp);
        }
        return terms.join('')||'0';
      })();

      ro.innerHTML =
        `<div><b>element index ${idx}</b> · as polynomial in α: <span style="color:var(--yellow)">${polyStr(e)}</span> · as g<sup>${powi}</sup></div>`+
        `<div>multiplicative order: <b>${ordEl}</b> (divides ${q-1})</div>`+
        `<div>Frobenius image (x ↦ x<sup>${p}</sup>): <span style="color:var(--pink)">${polyStr(frobEl)}</span></div>`+
        `<div>Frobenius orbit size: ${minDeg} · minimal polynomial over 𝔽<sub>${p}</sub>: <span style="color:var(--green)">${minPolyStr}</span> (degree ${minDeg})</div>`+
        `<div class="small">This element generates a subfield of size ${Math.pow(p,minDeg)} = 𝔽<sub>${p}${sup(minDeg)}</sub>.</div>`;
    }

    svg.querySelectorAll('[data-idx]').forEach(el=>{
      const idx = parseInt(el.getAttribute('data-idx'));
      el.addEventListener('click',()=>showInfo(idx));
      el.addEventListener('mouseenter',()=>showInfo(idx));
    });
    // initial info: show g
    if(gIdx>=0) showInfo(gIdx);
  }

  function polyStrX(c){
    // display with x variable
    if(!c.length) return '0';
    const terms=[];
    for(let i=c.length-1;i>=0;i--){
      if(c[i]===0) continue;
      let s = c[i]===1 && i>0 ? '' : ''+c[i];
      const xp = i===0?'':(i===1?'x':`x${sup(i)}`);
      if(terms.length) terms.push(' + '+s+xp);
      else terms.push(s+xp);
    }
    return terms.join('')||'0';
  }

  pSel.addEventListener('change',draw);
  nSel.addEventListener('change',draw);
  draw();
})();

