function mkZn(n){
  const els = Array.from({length:n},(_,i)=>String(i));
  const op = (i,j)=>mod(i+j,n);
  const subs = [];
  for(let d=1;d<=n;d++){
    if(n%d!==0) continue;
    const idx=[];
    for(let i=0;i<d;i++) idx.push((n/d)*i);
    subs.push({name:d===1?'{e}':(d===n?`ℤ/${n}ℤ (whole)`:`⟨${n/d}⟩ order ${d}`),idx});
  }
  return {name:`ℤ/${n}ℤ`,els,op,identity:0,abelian:true,subgroups:subs};
}
const S3 = (()=>{
  const perms = [[0,1,2],[1,0,2],[2,1,0],[0,2,1],[1,2,0],[2,0,1]];
  const names = ['e','(12)','(13)','(23)','(123)','(132)'];
  const apply = (p,q)=>q.map(k=>p[k]);
  const op = (i,j)=>{
    const r = apply(perms[i],perms[j]);
    return perms.findIndex(p=>p.every((v,k)=>v===r[k]));
  };
  return {name:'S₃',els:names,op,identity:0,abelian:false,
    subgroups:[
      {name:'{e}',idx:[0]},
      {name:'⟨(12)⟩',idx:[0,1]},
      {name:'⟨(13)⟩',idx:[0,2]},
      {name:'⟨(23)⟩',idx:[0,3]},
      {name:'A₃ = ⟨(123)⟩ (normal)',idx:[0,4,5]},
      {name:'S₃ (whole)',idx:[0,1,2,3,4,5]},
    ]};
})();
const D4 = (()=>{
  const names = ['1','r','r²','r³','s','sr','sr²','sr³'];
  const idx = (i,f)=>f*4+i;
  const decode = k=>({i:k%4,f:Math.floor(k/4)});
  const op = (a,b)=>{
    const A=decode(a),B=decode(b);
    const i = mod(A.i + (A.f?-1:1)*B.i, 4);
    const f = (A.f+B.f)%2;
    return idx(i,f);
  };
  return {name:'D₄',els:names,op,identity:0,abelian:false,
    subgroups:[
      {name:'{e}',idx:[0]},
      {name:'⟨r²⟩ (normal)',idx:[0,2]},
      {name:'⟨s⟩',idx:[0,4]},
      {name:'⟨sr⟩',idx:[0,5]},
      {name:'⟨r⟩ order 4 (normal)',idx:[0,1,2,3]},
      {name:'⟨s,r²⟩ (normal)',idx:[0,2,4,6]},
      {name:'D₄ (whole)',idx:[0,1,2,3,4,5,6,7]},
    ]};
})();

const GROUPS = {Z6:mkZn(6), Z12:mkZn(12), S3, D4};
const gSel = $('#co-group'), sSel = $('#co-sub');
const props = $('#co-props'), out = $('#co-out'), ro = $('#co-readout');

function renderSubs(){
  const G = GROUPS[gSel.value];
  sSel.innerHTML = '';
  for(let i=0;i<G.subgroups.length;i++){
    const o = document.createElement('option');
    o.value = i; o.textContent = G.subgroups[i].name;
    sSel.appendChild(o);
  }
  sSel.value = 0;
}

function inverseOf(G,g){
  for(let k=0;k<G.els.length;k++){
    if(G.op(g,k)===G.identity && G.op(k,g)===G.identity) return k;
  }
  return -1;
}

function leftCoset(G,H,g){
  const s = new Set();
  for(const h of H.idx) s.add(G.op(g,h));
  return [...s].sort((a,b)=>a-b);
}
function rightCoset(G,H,g){
  const s = new Set();
  for(const h of H.idx) s.add(G.op(h,g));
  return [...s].sort((a,b)=>a-b);
}

function partition(G,H,kind){
  const n = G.els.length;
  const seen = new Array(n).fill(-1);
  const blocks = [];
  for(let g=0;g<n;g++){
    if(seen[g]>=0) continue;
    const c = kind==='left' ? leftCoset(G,H,g) : rightCoset(G,H,g);
    const id = blocks.length;
    for(const x of c) seen[x]=id;
    blocks.push(c);
  }
  return {seen, blocks};
}

function isNormal(G,H){
  const L = partition(G,H,'left');
  const R = partition(G,H,'right');
  for(let g=0;g<G.els.length;g++) if(L.seen[g]!==R.seen[g]) return false;
  return true;
}

function drawRow(G,blocks,seen){
  const palette = ['var(--yellow)','var(--blue)','var(--green)','var(--pink)','var(--violet)','var(--cyan)','#f0c987','#9aa4b2'];
  let html = '<div style="display:flex;flex-wrap:wrap;gap:.35rem;margin:.3rem 0">';
  for(let g=0;g<G.els.length;g++){
    const c = palette[seen[g] % palette.length];
    html += `<span style="background:color-mix(in srgb, ${c} 22%, transparent);border:1px solid ${c};color:${c};padding:.15rem .5rem;border-radius:4px;font-family:ui-monospace,monospace;font-size:.85rem">${G.els[g]}</span>`;
  }
  html += '</div>';
  return html;
}

function draw(){
  const G = GROUPS[gSel.value];
  const H = G.subgroups[+sSel.value || 0];
  const L = partition(G,H,'left');
  const R = partition(G,H,'right');
  const normal = isNormal(G,H);
  const order = G.els.length, subOrder = H.idx.length;
  const numCosets = order/subOrder;
  props.innerHTML = `|G|=${order} · |H|=${subOrder} · [G:H]=${numCosets} · ${normal?'<span style="color:var(--green)">H is normal</span>':'<span style="color:var(--pink)">H is not normal</span>'}`;

  let html = '';
  html += '<div class="small" style="margin-top:.4rem;color:var(--mute)">Left cosets gH (partition of G):</div>';
  html += drawRow(G,L.blocks,L.seen);
  for(let i=0;i<L.blocks.length;i++){
    const rep = L.blocks[i][0];
    html += `<div class="small" style="color:var(--mute);margin:.1rem 0">coset ${i+1}: ${G.els[rep]}H = {${L.blocks[i].map(k=>G.els[k]).join(', ')}}</div>`;
  }
  html += '<div class="small" style="margin-top:.6rem;color:var(--mute)">Right cosets Hg (partition of G):</div>';
  html += drawRow(G,R.blocks,R.seen);
  for(let i=0;i<R.blocks.length;i++){
    const rep = R.blocks[i][0];
    html += `<div class="small" style="color:var(--mute);margin:.1rem 0">coset ${i+1}: H${G.els[rep]} = {${R.blocks[i].map(k=>G.els[k]).join(', ')}}</div>`;
  }
  out.innerHTML = html;

  ro.innerHTML = `Lagrange: |G|=|H|·[G:H] = ${subOrder}·${numCosets} = ${order}. ` +
    (normal
      ? `<span style="color:var(--green)">Left and right coset partitions coincide.</span> H is normal, so G/H is a group.`
      : `<span style="color:var(--pink)">Left and right coset partitions differ.</span> H is not normal; no quotient.`);
}

gSel.addEventListener('change',()=>{renderSubs();draw();});
sSel.addEventListener('change',draw);
renderSubs(); draw();

function mkZn(n){
