  }
  return {name:`ℤ/${n}ℤ`,els,op,identity:0,abelian:true,subgroups:subs};
}
const S3 = (()=>{
  const perms = [[0,1,2],[1,0,2],[2,1,0],[0,2,1],[1,2,0],[2,0,1]];
  const names = ['e','(12)','(13)','(23)','(123)','(132)'];
  const apply = (p,q)=>q.map(k=>p[k]);
  const op = (i,j)=>{
    const r = apply(perms[i],perms[j]);
    return perms.findIndex(p=>p.every((v,k)=>v===r[k]));
  };
  return {name:'S₃',els:names,op,identity:0,abelian:false,
