function factor(n){
  const out = {};
  for(let p=2; p*p<=n; p++){
    while(n%p===0){ out[p]=(out[p]||0)+1; n/=p; }
  }
  if(n>1) out[n]=(out[n]||0)+1;
  return out;
}
function partitions(n){
  // returns array of partitions (each a non-increasing array) of n
  if(n===0) return [[]];
  const out = [];
  function rec(rem, maxPart, cur){
    if(rem===0){ out.push(cur.slice()); return; }
    for(let k=Math.min(rem,maxPart); k>=1; k--){
      cur.push(k); rec(rem-k, k, cur); cur.pop();
    }
  }
  rec(n, n, []);
  return out;
}

const nIn = $('#ab-n'), btn = $('#ab-go');
const fact = $('#ab-fact'), out = $('#ab-out'), ro = $('#ab-readout');

function draw(){
  const n = Math.max(1, Math.min(1000, parseInt(nIn.value)||1));
  nIn.value = n;
  if(n===1){
    fact.textContent='';
    out.innerHTML = '<div class="small">The trivial group {e} is the only abelian group of order 1.</div>';
    ro.textContent = 'Count: 1.';
    return;
  }
  const F = factor(n);
  const primes = Object.keys(F).map(Number).sort((a,b)=>a-b);
  const factStr = primes.map(p=>F[p]===1?`${p}`:`${p}^${F[p]}`).join(' · ');
  fact.innerHTML = `n = ${n} = ${factStr}`;

  // per prime, partitions of v_p(n)
  const perPrime = primes.map(p=>({p, k:F[p], parts:partitions(F[p])}));
  // cartesian product
  let groups = [[]];
  for(const {p, parts} of perPrime){
    const next = [];
    for(const g of groups){
      for(const part of parts){
        next.push([...g, {p, part}]);
      }
    }
    groups = next;
  }

  // format each group as elementary divisors and invariant factors
  function sup(x){ return ''+[...String(x)].map(d=>'⁰¹²³⁴⁵⁶⁷⁸⁹'[+d]).join(''); }
  function elemDiv(g){
    const terms = [];
    for(const {p, part} of g){
      for(const a of part){
        terms.push(`ℤ/${p}${a===1?'':sup(a)}`);
      }
    }
    return terms.join(' ⊕ ');
  }
  function invariantFactors(g){
    // for each prime, pad its partitions with zeros to common length = max r across primes
    const maxR = Math.max(...g.map(x=>x.part.length));
    const perP = g.map(({p, part}) => {
      const padded = [];
      for(let i=0;i<maxR-part.length;i++) padded.push(0);
      padded.push(...part);
      return {p, padded};
    });
    // invariant factor d_i = product over primes of p^{padded[i]}
    const d = [];
    for(let i=0;i<maxR;i++){
      let val = 1;
      for(const {p, padded} of perP){
        val *= Math.pow(p, padded[i]);
      }
      d.push(val);
    }
    return d.filter(x=>x>1);
  }

  let html = '<div class="small" style="color:var(--mute);margin:.3rem 0">All abelian groups of order '+n+', up to isomorphism:</div>';
  html += '<div style="overflow:auto"><table class="cayley" style="margin-left:0"><tr><td class="hdr">#</td><td class="hdr">elementary divisors</td><td class="hdr">invariant factors</td></tr>';
  for(let i=0;i<groups.length;i++){
    const g = groups[i];
    const ed = elemDiv(g);
    const inv = invariantFactors(g);
    const invStr = inv.length===0 ? 'ℤ/1 (trivial)' : inv.map(d=>'ℤ/'+d).join(' ⊕ ');
    html += `<tr><td>${i+1}</td><td style="color:var(--yellow)">${ed}</td><td style="color:var(--green)">${invStr}</td></tr>`;
  }
  html += '</table></div>';
  out.innerHTML = html;

  const counts = primes.map(p=>`P(${F[p]})=${partitions(F[p]).length}`).join(' · ');
  ro.innerHTML = `Count = ${groups.length} = ${counts}.`;
}

