function parseCoeffs(s){
  // Accept space- or comma-separated. Highest degree first.
  const parts = s.trim().split(/[\s,]+/).filter(Boolean);
  const out = parts.map(p=>parseInt(p));
  if(out.some(x=>Number.isNaN(x))) return null;
  // trim leading zeros
  while(out.length>1 && out[0]===0) out.shift();
  return out;
}
function polyStr(c){
  // c: highest degree first
  if(c.length===0) return '0';
  const n = c.length-1;
  const terms=[];
  for(let i=0;i<c.length;i++){
    const a = c[i]; if(a===0) continue;
    const deg = n-i;
    const sign = a<0 ? '−' : (terms.length?'+':'');
    const abs = Math.abs(a);
    let coef = (abs===1 && deg>0) ? '' : String(abs);
    let xp = deg===0?'':(deg===1?'x':`x^${deg}`);
    terms.push((sign?(terms.length?' '+sign+' ':sign):'')+coef+xp);
  }
  return terms.join('')||'0';
}
function divisorsAbs(n){
  n = Math.abs(n); if(n===0) return [0];
  const ds = [];
  for(let d=1; d*d<=n; d++){
    if(n%d===0){ ds.push(d); if(d!==n/d) ds.push(n/d); }
  }
  return ds.sort((a,b)=>a-b);
}
function evalPoly(c, x){
  // x is rational p/q; use bignum-ish: since degrees small and ints bounded, just use numeric, accept possible rounding
  let v = 0;
  for(let i=0;i<c.length;i++) v = v*x + c[i];
  return v;
}
function gcdAll(c){
  let g = 0;
  for(const x of c) g = gcd(g, Math.abs(x));
  return g || 1;
}
function isPrimeN(p){ return isPrime(p); }

function eisensteinPrimes(c){
  // c[0] = leading, c[c.length-1] = constant
  const n = c.length-1;
  const an = c[0], a0 = c[c.length-1];
  if(a0===0) return [];
  const results = [];
  for(const p of [2,3,5,7,11]){
    if(an % p === 0) continue;
    let ok = true;
    for(let i=1;i<=n;i++){
      if(c[i] % p !== 0){ ok=false; break; }
    }
    if(!ok) continue;
    if(a0 % (p*p) === 0) continue;
    results.push(p);
  }
  return results;
}

function rationalRoots(c){
  const a0 = c[c.length-1], an = c[0];
  if(a0===0){
    // x=0 is a root
    return [{p:0,q:1}];
  }
  const P = divisorsAbs(a0), Q = divisorsAbs(an);
  const tried = new Set();
  const roots = [];
  for(const p of P){
    for(const q of Q){
      for(const sign of [1,-1]){
        const num = sign*p, den = q;
        const key = num+'/'+den;
        if(tried.has(key)) continue;
        tried.add(key);
        // simplify
        const g = gcd(Math.abs(num), Math.abs(den));
        const np = num/g, nq = den/g;
        // evaluate c(np/nq) * nq^n == 0 integer check
        const n = c.length-1;
        let total = 0n;
        for(let i=0;i<c.length;i++){
          const deg = n-i;
          // term = c[i] * np^deg * nq^(n-deg)
          let t = BigInt(c[i]);
          for(let j=0;j<deg;j++) t *= BigInt(np);
          for(let j=0;j<n-deg;j++) t *= BigInt(nq);
          total += t;
        }
        if(total===0n) roots.push({p:np, q:nq});
      }
    }
  }
  return roots;
}

const coefIn = $('#pi-coef'), btn = $('#pi-go'), disp = $('#pi-disp');
const out = $('#pi-out'), ro = $('#pi-readout');

