function draw(){
  const c = parseCoeffs(coefIn.value);
  if(!c || c.length===0){
    disp.innerHTML = '<span style="color:var(--pink)">parse error</span>';
    out.innerHTML = ''; ro.textContent=''; return;
  }
  disp.innerHTML = `f(x) = <span style="color:var(--yellow)">${polyStr(c)}</span> · degree ${c.length-1}`;
  const deg = c.length-1;

  let html = '';
  if(deg===0){
    html += '<div class="small">Constant polynomial: not considered for irreducibility tests.</div>';
    out.innerHTML = html; ro.textContent=''; return;
  }
  if(deg===1){
    html += '<div class="small" style="color:var(--green)">Degree-1: always irreducible over any field.</div>';
    out.innerHTML = html; ro.innerHTML='Irreducible (trivially, deg 1).'; return;
  }
  // content
  const ct = gcdAll(c);
  html += `<div class="small" style="color:var(--mute)">Content gcd = ${ct}${ct>1?' · NOT primitive — divide out':' · primitive'}.</div>`;

  // (a) Eisenstein
  const eis = eisensteinPrimes(c);
  html += '<div class="small" style="margin-top:.4rem;color:var(--mute)">Eisenstein at small primes (p≤11):</div>';
  if(eis.length){
    html += `<div style="color:var(--green)">✓ Eisenstein applies at p = ${eis.join(', ')} ⇒ <b>irreducible over ℚ</b>.</div>`;
  } else {
    html += '<div style="color:var(--mute)">Eisenstein does not directly apply at any p ≤ 11.</div>';
  }

  // (b) Rational-root test
  html += '<div class="small" style="margin-top:.4rem;color:var(--mute)">Rational-root test (candidates ±p/q with p∣a₀, q∣aₙ):</div>';
  const roots = rationalRoots(c);
  if(roots.length){
    html += `<div style="color:var(--pink)">× rational root(s) found: ${roots.map(r=>r.q===1?String(r.p):`${r.p}/${r.q}`).join(', ')} ⇒ <b>reducible over ℚ</b> (has a linear factor).</div>`;
  } else {
    html += '<div style="color:var(--mute)">No rational roots ⇒ no linear factor over ℚ.</div>';
  }

  // verdict
  let verdict = '';
  if(eis.length) verdict = 'irreducible over ℚ (Eisenstein)';
  else if(roots.length) verdict = 'reducible over ℚ (has a rational root)';
  else if(deg===2 || deg===3) verdict = 'irreducible over ℚ (no rational root and deg ≤ 3)';
  else verdict = 'inconclusive from these tests alone (could still be reducible into higher-degree factors; try mod-p reduction or factorization algorithms)';
  ro.innerHTML = `Verdict: <b style="color:${eis.length||(deg===2||deg===3)&&!roots.length?'var(--green)':(roots.length?'var(--pink)':'var(--yellow)')}">${verdict}</b>.`;

  out.innerHTML = html;
}

