const nSl = $('#sd-n'), nV = $('#sd-nv');
const btnT = $('#sd-triv'), btnI = $('#sd-inv');
const out = $('#sd-out'), ro = $('#sd-readout');

let inv = false; // false = trivial φ, true = inversion

btnT.addEventListener('click',()=>{inv=false;btnT.classList.add('active');btnI.classList.remove('active');draw();});
btnI.addEventListener('click',()=>{inv=true;btnI.classList.add('active');btnT.classList.remove('active');draw();});
nSl.addEventListener('input',()=>{nV.textContent=nSl.value;draw();});

function draw(){
  const n = +nSl.value;
  nV.textContent = n;
  // elements of N⋊H: (a, b) with a∈Z/n, b∈{0,1}
  // product: (a1,b1)(a2,b2) = (a1 + φ_{b1}(a2), b1+b2 mod 2)
  // φ trivial: identity on N; φ inversion (only when b=1): a → -a
  function phi(b,a){
    if(!inv) return a;
    return b===0 ? a : mod(-a, n);
  }
  const elNames = [];
  for(let b=0;b<2;b++) for(let a=0;a<n;a++){
    if(b===0) elNames.push(a===0?'e':`r${a===1?'':sup(a)}`);
    else     elNames.push(a===0?'s':`r${a===1?'':sup(a)}s`);
  }
  function idx(a,b){ return b*n + a; }
  function decode(k){ return {a:k%n, b:Math.floor(k/n)}; }
  const m = 2*n;
  function op(i,j){
    const A=decode(i), B=decode(j);
    const a = mod(A.a + phi(A.b, B.a), n);
    const b = (A.b + B.b) % 2;
    return idx(a,b);
  }
  // build cayley
  let html = '<div class="small" style="color:var(--mute);margin:.3rem 0">Cayley table of G = ℤ/'+n+' ⋊<sub>φ</sub> ℤ/2 (|G|='+m+'):</div>';
  html += '<div style="overflow:auto"><table class="cayley"><tr><td class="hdr">·</td>';
  for(let j=0;j<m;j++) html += `<td class="hdr">${elNames[j]}</td>`;
  html += '</tr>';
  for(let i=0;i<m;i++){
    html += `<tr><td class="hdr">${elNames[i]}</td>`;
    for(let j=0;j<m;j++){
      const v = op(i,j);
      const c = i<n && j<n ? 'var(--yellow)' : (i<n || j<n ? 'var(--green)' : 'var(--pink)');
      html += `<td style="color:${c}">${elNames[v]}</td>`;
    }
    html += '</tr>';
  }
  html += '</table></div>';

  // SES diagram
  html += '<div style="text-align:center;margin:.8rem 0;font-family:ui-monospace,monospace;color:var(--mute)">1 → <span style="color:var(--yellow)">ℤ/'+n+'</span> <span style="color:var(--mute)">→</span> <span style="color:var(--blue)">G</span> <span style="color:var(--mute)">→</span> <span style="color:var(--green)">ℤ/2</span> → 1</div>';

  // abelian check
  let abel = true;
  for(let i=0;i<m && abel;i++)
    for(let j=0;j<m && abel;j++)
      if(op(i,j) !== op(j,i)) abel = false;

  const name = !inv
    ? (n===1 ? 'ℤ/2' : `ℤ/${n} × ℤ/2 = ℤ/${2*n/gcd(n,2)} (abelian, direct product)`)
    : (n===1 ? 'ℤ/2' : (n===2 ? 'V₄ (inversion is trivial on ℤ/2)' : `D${sup(n)} (dihedral group of order ${2*n})`));

  out.innerHTML = html;
  ro.innerHTML = `|G| = ${m}. ${abel?'<span style="color:var(--green)">Abelian</span>':'<span style="color:var(--pink)">Non-abelian</span>'}. Identification: <b style="color:var(--yellow)">${name}</b>. ` +
    (inv && n>=3 ? 'The inversion twist reproduces the dihedral relation srs=r⁻¹.' : '');
}
function sup(x){ return ''+[...String(x)].map(d=>'⁰¹²³⁴⁵⁶⁷⁸⁹'[+d]).join(''); }

