const gSel = $('#jh-group'), sSel = $('#jh-series'), out = $('#jh-out'), ro = $('#jh-readout'), info = $('#jh-info');

function renderSeriesOpts(){
  const G = CATALOG[gSel.value];
  sSel.innerHTML = '';
  for(let i=0;i<G.series.length;i++){
    const o = document.createElement('option');
    o.value = i; o.textContent = G.series[i].name;
    sSel.appendChild(o);
  }
  sSel.value = 0;
