function multisetEqual(a,b){
  if(a.length!==b.length) return false;
  const sa = [...a].sort().join('|');
  const sb = [...b].sort().join('|');
  return sa===sb;
}

function draw(){
  const G = CATALOG[gSel.value];
  const S = G.series[+sSel.value || 0];
  info.innerHTML = `|G| = ${G.order} · ${G.series.length} series catalogued`;

  // Render the chain as a vertical stack with simple-factor labels between rungs
  let html = '<div style="display:flex;flex-direction:column;align-items:center;gap:0;margin:.6rem 0">';
  for(let i=S.chain.length-1; i>=0; i--){
    const [name,ord] = S.chain[i];
    const isTop = i===S.chain.length-1, isBot = i===0;
    const color = isTop ? 'var(--yellow)' : (isBot ? 'var(--mute)' : 'var(--blue)');
    html += `<div style="background:color-mix(in srgb, ${color} 12%, transparent);border:1px solid ${color};color:${color};padding:.3rem .9rem;border-radius:6px;font-family:ui-monospace,monospace;font-size:.92rem;min-width:9rem;text-align:center">${name} <span style="color:var(--mute);font-size:.78rem">|·| = ${ord}</span></div>`;
    if(i>0){
      const factor = S.factors[i-1];
      html += `<div style="display:flex;align-items:center;gap:.5rem;color:var(--green);font-family:ui-monospace,monospace;font-size:.85rem;margin:.18rem 0"><span>↓</span><span style="background:color-mix(in srgb, var(--green) 12%, transparent);padding:.1rem .5rem;border-radius:4px">factor: ${factor}</span></div>`;
    }
  }
  html += '</div>';

  // Show factor multiset for ALL series, side-by-side, to visualize Jordan–Hölder
  html += '<div class="small" style="color:var(--mute);margin:.6rem 0 .2rem">Factor multisets (Jordan–Hölder check):</div>';
  html += '<div style="display:flex;flex-wrap:wrap;gap:.6rem">';
  const baseSorted = [...G.series[0].factors].sort();
  for(let i=0;i<G.series.length;i++){
    const T = G.series[i];
    const same = multisetEqual(T.factors, G.series[0].factors);
    const c = same ? 'var(--green)' : 'var(--pink)';
    const sortedShow = [...T.factors].sort().join(' + ');
    html += `<div style="border:1px solid ${c};background:color-mix(in srgb,${c} 8%,transparent);color:${c};padding:.3rem .6rem;border-radius:6px;font-family:ui-monospace,monospace;font-size:.85rem">${T.name}: ${T.factors.join(', ')} <span style="color:var(--mute)">(sorted: ${sortedShow})</span></div>`;
  }
  html += '</div>';

  out.innerHTML = html;

  const allSame = G.series.every(T=>multisetEqual(T.factors, G.series[0].factors));
  ro.innerHTML = `Composition length n = ${S.chain.length-1}. Factor multiset (sorted) = {${baseSorted.join(', ')}}. ` +
    (allSame
      ? `<span style="color:var(--green)">The ${G.series.length} catalogued series share the same multiset of simple factors</span> — as Jordan–Hölder predicts.`
      : `<span style="color:var(--pink)">Multisets disagree — that would contradict Jordan–Hölder!</span>`);
}

gSel.addEventListener('change',()=>{renderSeriesOpts();draw();});
sSel.addEventListener('change',draw);
renderSeriesOpts(); draw();

// For each group we encode the derived series as a list of (name, order) tuples.
// Series stalls when a perfect subgroup G^(k) = G^(k+1) ≠ {e} appears.
const SERIES = {
  Z12: { name:'ℤ/12ℤ', chain:[['ℤ/12ℤ',12],['{e}',1]], stalls:false, solvable:true },
  S3:  { name:'S₃',    chain:[['S₃',6],['A₃',3],['{e}',1]], stalls:false, solvable:true },
  D4:  { name:'D₄',    chain:[['D₄',8],['⟨r²⟩',2],['{e}',1]], stalls:false, solvable:true },
  S4:  { name:'S₄',    chain:[['S₄',24],['A₄',12],['V₄',4],['{e}',1]], stalls:false, solvable:true },
  A4:  { name:'A₄',    chain:[['A₄',12],['V₄',4],['{e}',1]], stalls:false, solvable:true },
  A5:  { name:'A₅',    chain:[['A₅',60],['A₅',60]], stalls:true, solvable:false, stallNote:'A₅ is perfect: A₅\' = A₅' },
  S5:  { name:'S₅',    chain:[['S₅',120],['A₅',60],['A₅',60]], stalls:true, solvable:false, stallNote:'A₅ is perfect — chain stalls at A₅' },
};

const gSel = $('#sv-group'), out = $('#sv-out'), ro = $('#sv-readout'), info = $('#sv-info');

function draw(){
  const S = SERIES[gSel.value];
  info.innerHTML = `|G| = ${S.chain[0][1]} · ${S.solvable ? '<span style="color:var(--green)">solvable</span>' : '<span style="color:var(--pink)">not solvable</span>'}`;

  let html = '<div style="display:flex;flex-direction:column;align-items:center;gap:0;margin:.6rem 0">';
  for(let i=0;i<S.chain.length;i++){
    const [name,ord] = S.chain[i];
    const isStallRepeat = S.stalls && i>0 && S.chain[i][0]===S.chain[i-1][0];
    const color = i===0 ? 'var(--yellow)' : (isStallRepeat ? 'var(--pink)' : (ord===1 ? 'var(--green)' : 'var(--blue)'));
    const label = `G<sup>(${i})</sup> = ${name}`;
    html += `<div style="background:color-mix(in srgb, ${color} 12%, transparent);border:1px solid ${color};color:${color};padding:.3rem .9rem;border-radius:6px;font-family:ui-monospace,monospace;font-size:.92rem;min-width:11rem;text-align:center">${label} <span style="color:var(--mute);font-size:.78rem">|·| = ${ord}</span></div>`;
    if(i<S.chain.length-1){
      const arrow = isStallRepeat || (i+1<S.chain.length && S.stalls && S.chain[i+1][0]===S.chain[i][0]) ? '↺ stalls' : '⊇ commutator';
      const ac = arrow.startsWith('↺') ? 'var(--pink)' : 'var(--mute)';
      html += `<div style="color:${ac};font-family:ui-monospace,monospace;font-size:.78rem;margin:.18rem 0">${arrow}</div>`;
    }
  }
  html += '</div>';

  if(S.stalls){
    html += `<div class="small" style="color:var(--pink);text-align:center">${S.stallNote}</div>`;
  }

  out.innerHTML = html;

  const len = S.solvable ? S.chain.length-1 : '∞';
  ro.innerHTML = S.solvable
    ? `Derived length ℓ(G) = ${len}. <span style="color:var(--green)">Series terminates</span>, every composition factor is cyclic of prime order.`
    : `Derived series <span style="color:var(--pink)">never reaches {e}</span> — G is not solvable. By Galois, polynomials with this Galois group are not solvable by radicals.`;
}

gSel.addEventListener('change',draw);
draw();

// Each entry: lower central series as (name, order) and Sylow decomposition.
// nilpotent ⟺ chain terminates at {e} ⟺ G is direct product of its Sylow subgroups.
const DATA = {
  Z12: { name:'ℤ/12ℤ', order:12, lcs:[['ℤ/12ℤ',12],['{e}',1]], sylows:[['Syl₂',4,'ℤ/4'],['Syl₃',3,'ℤ/3']], directProduct:true, nilpotent:true },
  D4:  { name:'D₄',    order:8,  lcs:[['D₄',8],['⟨r²⟩',2],['{e}',1]], sylows:[['Syl₂',8,'D₄ itself']], directProduct:true, nilpotent:true },
  Q8:  { name:'Q₈',    order:8,  lcs:[['Q₈',8],['{±1}',2],['{e}',1]], sylows:[['Syl₂',8,'Q₈ itself']], directProduct:true, nilpotent:true },
  S3:  { name:'S₃',    order:6,  lcs:[['S₃',6],['A₃',3],['A₃',3]], sylows:[['Syl₂',2,'⟨(12)⟩, ⟨(13)⟩, ⟨(23)⟩ — three copies, none normal'],['Syl₃',3,'A₃ (unique, normal)']], directProduct:false, nilpotent:false, stallNote:'γ_i S₃ stabilizes at A₃ ≠ {e}' },
  S4:  { name:'S₄',    order:24, lcs:[['S₄',24],['A₄',12],['V₄',4],['V₄',4]], sylows:[['Syl₂',8,'three conjugate D₄ copies'],['Syl₃',3,'four conjugate ℤ/3 copies']], directProduct:false, nilpotent:false, stallNote:'γ_i S₄ stabilizes at V₄ ≠ {e}' },
  A4:  { name:'A₄',    order:12, lcs:[['A₄',12],['V₄',4],['V₄',4]], sylows:[['Syl₂',4,'V₄ (unique, normal)'],['Syl₃',3,'four conjugate ℤ/3 copies — not normal']], directProduct:false, nilpotent:false, stallNote:'γ_i A₄ stabilizes at V₄ ≠ {e}' },
};

const gSel = $('#nl-group'), out = $('#nl-out'), ro = $('#nl-readout'), info = $('#nl-info');

function draw(){
  const D = DATA[gSel.value];
  info.innerHTML = `|G| = ${D.order} · ${D.nilpotent ? '<span style="color:var(--green)">nilpotent</span>' : '<span style="color:var(--pink)">not nilpotent</span>'}`;

  // Lower central chain
  let html = '<div class="small" style="color:var(--mute);margin:.4rem 0 .2rem">Lower central series γ_i G:</div>';
  html += '<div style="display:flex;flex-direction:column;align-items:center;gap:0;margin:.3rem 0 .8rem">';
  for(let i=0;i<D.lcs.length;i++){
    const [name,ord] = D.lcs[i];
    const stallRepeat = !D.nilpotent && i>0 && D.lcs[i][0]===D.lcs[i-1][0];
    const color = i===0 ? 'var(--yellow)' : (stallRepeat ? 'var(--pink)' : (ord===1 ? 'var(--green)' : 'var(--blue)'));
    html += `<div style="background:color-mix(in srgb, ${color} 12%, transparent);border:1px solid ${color};color:${color};padding:.28rem .8rem;border-radius:6px;font-family:ui-monospace,monospace;font-size:.9rem;min-width:11rem;text-align:center">γ<sub>${i+1}</sub> G = ${name} <span style="color:var(--mute);font-size:.78rem">|·| = ${ord}</span></div>`;
    if(i<D.lcs.length-1){
      const stallHere = !D.nilpotent && D.lcs[i+1][0]===D.lcs[i][0];
      const arrow = stallHere ? '↺ stalls' : '[·, G]';
      const ac = stallHere ? 'var(--pink)' : 'var(--mute)';
      html += `<div style="color:${ac};font-family:ui-monospace,monospace;font-size:.78rem;margin:.16rem 0">${arrow}</div>`;
    }
  }
  html += '</div>';
  if(D.stallNote){
    html += `<div class="small" style="color:var(--pink);text-align:center;margin-bottom:.6rem">${D.stallNote}</div>`;
  }

  // Sylow decomposition
  html += '<div class="small" style="color:var(--mute);margin:.6rem 0 .2rem">Sylow subgroups:</div>';
  html += '<div style="display:flex;flex-wrap:wrap;gap:.45rem;justify-content:center">';
  for(const [tag,ord,note] of D.sylows){
    const c = D.directProduct ? 'var(--green)' : 'var(--pink)';
    html += `<div style="border:1px solid ${c};background:color-mix(in srgb,${c} 8%,transparent);color:${c};padding:.25rem .55rem;border-radius:6px;font-family:ui-monospace,monospace;font-size:.82rem">${tag} (order ${ord}): <span style="color:var(--mute)">${note}</span></div>`;
  }
  html += '</div>';

  out.innerHTML = html;

  if(D.nilpotent){
    const cls = D.lcs.length-1;
    ro.innerHTML = `Nilpotent of class ${cls}. <span style="color:var(--green)">G is the direct product of its Sylow subgroups</span>, ${D.sylows.map(s=>`|Syl| = ${s[1]}`).join(' · ')}. ${D.order===D.sylows[0][1] ? 'A single-prime case (every p-group is nilpotent).' : ''}`;
  } else {
    ro.innerHTML = `<span style="color:var(--pink)">Not nilpotent</span> — at least one Sylow subgroup is not normal, so G is not the direct product of its Sylow subgroups.`;
  }
}

gSel.addEventListener('change',draw);
draw();

const wIn = $('#fr-word'), bStep = $('#fr-step'), bReset = $('#fr-reset'), bFull = $('#fr-full');
const out = $('#fr-out'), ro = $('#fr-readout'), info = $('#fr-info');

// Internal model: array of letters drawn from {a,b,A,B}.
// Inverse map: a↔A, b↔B.
const INV = {a:'A',b:'B',A:'a',B:'b'};
const PRETTY = {a:'a', b:'b', A:'a⁻¹', B:'b⁻¹'};

let original = '';   // raw input parsed
let history = [];    // list of states; history[history.length-1] is current

function parse(s){
  const letters = [];
  for(const ch of s){
    if(ch==='a'||ch==='b'||ch==='A'||ch==='B') letters.push(ch);
  }
  return letters;
}

function findCancel(letters){
  for(let i=0;i<letters.length-1;i++){
    if(INV[letters[i]] === letters[i+1]) return i;
  }
  return -1;
}

function stepOnce(){
  const cur = history[history.length-1];
  const i = findCancel(cur);
  if(i<0) return false;
  const next = cur.slice(0,i).concat(cur.slice(i+2));
  history.push({letters:next, cancelAt:i, prev:cur});
  return true;
}

function reduceFully(){
  let safety = 1000;
  while(stepOnce() && safety-->0){}
}

function reset(){
  original = parse(wIn.value);
  history = [{letters:original.slice(), cancelAt:-1, prev:null}];
  draw();
}

function letterSpan(ch, opts={}){
  const c = (ch==='a'||ch==='A') ? 'var(--yellow)' : 'var(--cyan)';
  const isInv = (ch==='A'||ch==='B');
  const bg = opts.cancel ? 'color-mix(in srgb, var(--pink) 32%, transparent)' : `color-mix(in srgb, ${c} 14%, transparent)`;
  const border = opts.cancel ? 'var(--pink)' : c;
  return `<span style="display:inline-block;background:${bg};border:1px solid ${border};color:${isInv?c:c};padding:.15rem .45rem;margin:.05rem;border-radius:5px;font-family:ui-monospace,monospace;font-size:.95rem">${PRETTY[ch]}</span>`;
}

function draw(){
  const cur = history[history.length-1];
  const reduced = findCancel(cur.letters)<0;
  info.innerHTML = `original length ${original.length} · current length ${cur.letters.length} · ${reduced?'<span style="color:var(--green)">reduced</span>':'<span style="color:var(--yellow)">not reduced</span>'}`;

  let html = '<div class="small" style="color:var(--mute);margin:.4rem 0 .2rem">History (each step cancels one inverse pair):</div>';
  html += '<div style="display:flex;flex-direction:column;gap:.35rem">';
  for(let h=0;h<history.length;h++){
    const state = history[h];
    let row = `<div style="display:flex;align-items:center;gap:.3rem;flex-wrap:wrap"><span style="color:var(--mute);font-family:ui-monospace,monospace;font-size:.78rem;min-width:3.5rem">step ${h}:</span>`;
    if(state.letters.length===0){
      row += '<span style="color:var(--green);font-style:italic">e (identity)</span>';
    } else {
      // For previous-step row: show cancellation positions highlighted in pink
      const nextState = history[h+1];
      const ci = nextState ? nextState.cancelAt : -1;
      for(let i=0;i<state.letters.length;i++){
        row += letterSpan(state.letters[i], {cancel: (ci>=0 && (i===ci||i===ci+1))});
      }
    }
    row += '</div>';
    html += row;
  }
  html += '</div>';

  out.innerHTML = html;

  const finalWord = cur.letters.length===0 ? 'e' : cur.letters.map(c=>PRETTY[c]).join('');
  ro.innerHTML = reduced
    ? `Reduced form: <b style="color:var(--yellow)">${finalWord}</b>. ${cur.letters.length===0 ? 'The word represents the identity in F₂.' : 'Distinct reduced words represent distinct elements of F₂ (no further relations to apply).'}`
    : `Cancellation pending — click <b>step</b> or <b>reduce fully</b>. The leftmost inverse pair is at position ${findCancel(cur.letters)+1}.`;
}

bStep.addEventListener('click',()=>{ if(stepOnce()) draw(); });
bFull.addEventListener('click',()=>{ reduceFully(); draw(); });
bReset.addEventListener('click',reset);
wIn.addEventListener('change',reset);
wIn.addEventListener('input',reset);

reset();
